PutKvWithHighCapacity.description:
本接口与[PutKv](~~PutKv~~)的功能一样，只是允许上传更大请求体。当请求体较小时推荐直接使用[PutKv](~~PutKv~~)接口，从而减少服务端处理时间。本接口需要使用SDK进行调用。以golang SDK为例，需要使用PutKvWithHighCapacityAdvance函数进行调用。
```
func TestPutKvWithHighCapacity() {
	// 配置初始化
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// 构造待上传的键值对请求
	namespace := "test-put-kv"
	key := "test_PutKvWithHighCapacity_0"
	value := strings.Repeat("t", 10*1024*1024)
	rawReq := &PutKvRequest{
		Namespace: &namespace,
		Key:       &key,
		Value:     &value,
	}
	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// 如果payload大于2M，则调用大容量接口进行上传
	reqHighCapacity := &PutKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		Key:       &key,
		UrlObject: bytes.NewReader([]byte(payload)),
	}

	resp, err := cli.PutKvWithHighCapacityAdvance(reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}
